import pytest
@pytest.mark.parametrize('value',[float('nan'),float('inf')])
def test_finite_bootstrap_inputs(value):
    import math
    from twlab.evaluation import WeeklyObservation, block_bootstrap_mean, ObservationError
    o = WeeklyObservation('2026-W37','f','historical_numeric_temporally_controlled',False,True,value)
    try:
        r = block_bootstrap_mean([o],block_length=1,n_boot=10,seed=1)
    except ObservationError:
        return
    assert all(math.isfinite(x) for x in (r.mean,r.ci_low,r.ci_high))

def test_calibrator_requires_boolean_evidence():
    from tests.test_master import R
    from tests.test_schema import base, packet
    from twlab.schemas import CalibratorRecord, validate_prediction
    o = base()
    o['ranking'][0].update(calibrated_probability=0.9,calibration_model_id='cal')
    try:
        registry = {'cal':CalibratorRecord('cal',R(2025,12,31),'false')}
    except (TypeError, ValueError):
        return
    assert validate_prediction(o,packet(),known_calibrators=registry)
